css:
.jtc-container {
    padding: 28px;
    background: #eef1f4;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1b2230;
}
.jtc-header {
    background: linear-gradient(120deg, #141a26 0%, #20293a 100%);
    color: #f4f6f9;
    padding: 28px 32px;
    border-radius: 6px;
    border-left: 5px solid #d8232a;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(20, 26, 38, 0.18);
}
.jtc-header h1 {
    margin: 0 0 6px 0;
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 0.01em;
}
.jtc-subtitle {
    color: #9fb0c6;
    font-size: 0.95rem;
    font-style: italic;
    letter-spacing: 0.01em;
}
.jtc-period-counter {
    background: #ffffff;
    border: 1px solid #d3dae3;
    border-radius: 6px;
    padding: 14px 20px;
    margin-bottom: 20px;
    font-size: 0.95rem;
    color: #4a586c;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}
.jtc-period-counter #currentDay,
.jtc-period-counter #maxPeriods {
    font-weight: 700;
    color: #141a26;
}
.jtc-period-counter .jtc-round-name {
    margin-left: 16px;
    color: #d8232a;
    font-weight: 700;
    letter-spacing: 0.01em;
}
.jtc-briefing {
    background: #ffffff;
    border: 1px solid #d3dae3;
    border-top: 3px solid #d8232a;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.jtc-briefing h3 {
    margin: 0 0 10px 0;
    font-size: 1.08rem;
    color: #141a26;
    font-weight: 700;
    letter-spacing: 0.01em;
}
.jtc-briefing #briefingText {
    color: #36435a;
    font-size: 0.95rem;
    line-height: 1.62;
}
.jtc-briefing #briefingText strong { color: #141a26; }
.jtc-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.jtc-status-card {
    background: #ffffff;
    border: 1px solid #d3dae3;
    border-radius: 6px;
    padding: 18px 18px 16px;
    border-top: 3px solid #6b7891;
    box-shadow: 0 1px 3px rgba(20, 26, 38, 0.05);
}
.jtc-card-fri { border-top-color: #d8232a; grid-column: span 1; }
.jtc-card-mix { border-top-color: #2e7d5b; }
.jtc-card-cash { border-top-color: #b8860b; }
.jtc-card-build { border-top-color: #2b5fb0; }
.jtc-card-pool { border-top-color: #5a6678; }
.jtc-status-card .jtc-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: #6b7891;
    margin-bottom: 8px;
    font-weight: 700;
}
.jtc-status-card .jtc-value {
    font-size: 1.4rem;
    font-weight: 700;
    color: #141a26;
    line-height: 1.15;
}
.jtc-status-card .jtc-value-hero {
    font-size: 2.6rem;
    font-weight: 800;
    color: #d8232a;
    letter-spacing: -0.01em;
}
.jtc-controls {
    background: #ffffff;
    border: 1px solid #d3dae3;
    border-radius: 6px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.jtc-controls h3 {
    margin: 0 0 16px 0;
    font-size: 1.05rem;
    color: #141a26;
    font-weight: 700;
    border-bottom: 1px solid #e4e8ee;
    padding-bottom: 10px;
}
.jtc-controls label {
    display: block;
    color: #36435a;
    font-size: 0.88rem;
    font-weight: 600;
    margin: 16px 0 6px;
    letter-spacing: 0.01em;
}
.jtc-controls input[type="number"],
.jtc-controls input[type="text"],
.jtc-controls select {
    width: 100%;
    background: #f9fafc;
    border: 1px solid #c3ccd8;
    color: #141a26;
    border-radius: 4px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
}
.jtc-controls select option {
    background: #ffffff;
    color: #141a26;
}
.jtc-controls input:focus,
.jtc-controls select:focus {
    outline: none;
    border-color: #d8232a;
    box-shadow: 0 0 0 3px rgba(216, 35, 42, 0.16);
}
.jtc-controls .btn {
    margin-top: 22px;
    margin-right: 10px;
    border-radius: 4px;
    font-weight: 700;
    letter-spacing: 0.03em;
    padding: 11px 26px;
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.jtc-controls .btn-primary {
    background: #d8232a;
    border-color: #d8232a;
    color: #ffffff;
}
.jtc-controls .btn-primary:hover {
    background: #b91d23;
    border-color: #b91d23;
}
.jtc-controls .btn-outline-secondary {
    color: #4a586c;
    border-color: #c3ccd8;
    background: #ffffff;
}
.jtc-controls .btn-outline-secondary:hover {
    background: #eef1f4;
    color: #141a26;
    border-color: #adb7c5;
}
.jtc-history-wrap, .jtc-chart-wrap {
    background: #ffffff;
    border: 1px solid #d3dae3;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.jtc-history-wrap h3 {
    margin: 0 0 14px 0;
    font-size: 1.05rem;
    color: #141a26;
    font-weight: 700;
}
#usfHistoryTable {
    width: 100%;
    border-collapse: collapse;
}
#usfHistoryTable thead th {
    background: #f3f5f8;
    color: #141a26;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 2px solid #d8232a;
    padding: 10px 12px;
    text-align: left;
}
#usfHistoryTable tbody td {
    color: #36435a;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #edeff3;
}
#usfHistoryTable tbody tr:nth-child(even) td {
    background: #fafbfc;
}
.jtc-chart-wrap {
    height: 360px;
    position: relative;
}
@media (max-width: 768px) {
    .jtc-container { padding: 16px; }
    .jtc-header { padding: 20px; }
    .jtc-header h1 { font-size: 1.18rem; }
    .jtc-controls { padding: 18px 20px; }
    .jtc-history-wrap, .jtc-chart-wrap { padding: 16px 18px; }
    .jtc-status-card .jtc-value { font-size: 1.18rem; }
    .jtc-status-card .jtc-value-hero { font-size: 2rem; }
    .jtc-period-counter .jtc-round-name { margin-left: 0; flex-basis: 100%; }
    .jtc-chart-wrap { height: 300px; }
}


/* FIX v1.1.0 — completion / board-verdict screen */
.jtc-completion { padding: 10px 6px; text-align: center; }
.jtc-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.jtc-completion-score { font-size: 20px; color: #0f172a; margin-bottom: 14px; }
.jtc-completion-score strong { color: #4338ca; }
.jtc-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.jtc-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 104px; }
.jtc-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.jtc-completion-metric strong { font-size: 16px; color: #0f172a; }
.jtc-completion-verdict { max-width: 680px; margin: 0 auto 12px; text-align: left; padding: 12px 16px; background: #f8fafc; border-left: 3px solid #4338ca; border-radius: 4px; color: #1e293b; font-size: 14px; line-height: 1.5; }
.jtc-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.jtc-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #eef2ff; border-left: 3px solid #6366f1; border-radius: 4px; color: #1e293b; font-size: 13px; }

