(function() {
    'use strict';

    class JumpCurveAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Jump the Curve';
            this.version = '1.1.0';

            // Fixed binding constraint: CHF 300m pool over three years.
            this.POOL = 300;
            // Mature core operating cash engine: CHF 342m (18% of CHF 1.9bn).
            this.BASE_CASH = 342;
            // New-curve share of revenue today: under 4%.
            this.START_MIX = 3.8;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    pool: this.POOL,
                    capitalUsed: 0,
                    poolRemaining: this.POOL,
                    newMix: this.START_MIX,
                    coreCash: this.BASE_CASH,
                    capabilityBuild: 0,
                    fri: 0,
                    diagnosisRight: false,
                    timing: null,
                    route: null,
                    bet: null,
                    timingLabel: '—',
                    routeLabel: '—',
                    betLabel: '—',
                    friHistory: [],
                    mixHistory: [],
                    cashHistory: [],
                    buildHistory: [],
                    roundScore: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 50);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var round = state.currentPeriod || 1;
            var ds = state.domainState;

            if (round === 1) {
                var pos = (document.getElementById('curvePosInput') || {}).value;
                var cross = (document.getElementById('crossoverInput') || {}).value;
                var sig = (document.getElementById('signalInput') || {}).value;
                if (!pos || !cross || !sig) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r1'), 'warning');
                    return false;
                }
                decisions.curvePos = pos;
                decisions.crossover = cross;
                decisions.signal = sig;
                return true;
            }

            if (round === 2) {
                var timing = (document.getElementById('timingInput') || {}).value;
                var year1 = parseFloat((document.getElementById('year1Input') || {}).value);
                var trigger = (document.getElementById('triggerInput') || {}).value;
                if (!timing) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_timing'), 'warning');
                    return false;
                }
                if (!Number.isFinite(year1) || year1 < 0 || year1 > this.POOL) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_year1'), 'warning');
                    return false;
                }
                if (!trigger) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_trigger'), 'warning');
                    return false;
                }
                decisions.timing = timing;
                decisions.year1 = year1;
                decisions.trigger = trigger;
                return true;
            }

            if (round === 3) {
                var route = (document.getElementById('routeInput') || {}).value;
                var rdCut = parseFloat((document.getElementById('rdCutInput') || {}).value);
                var harvest = parseFloat((document.getElementById('harvestInput') || {}).value);
                var year23 = parseFloat((document.getElementById('year23Input') || {}).value);
                if (!route) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_route'), 'warning');
                    return false;
                }
                if (!Number.isFinite(rdCut) || rdCut < 0 || rdCut > 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_rdcut'), 'warning');
                    return false;
                }
                if (!Number.isFinite(harvest) || harvest < 0 || harvest > 120) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_harvest'), 'warning');
                    return false;
                }
                if (!Number.isFinite(year23) || year23 < 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_year23'), 'warning');
                    return false;
                }
                // The pool is the binding constraint: Year-1 + Years-2/3 may not exceed CHF 300m.
                if ((ds.capitalUsed + year23) > this.POOL) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_pool'), 'warning');
                    return false;
                }
                decisions.route = route;
                decisions.rdCut = rdCut;
                decisions.harvest = harvest;
                decisions.year23 = year23;
                return true;
            }

            if (round === 4) {
                var bet = (document.getElementById('betInput') || {}).value;
                var incentive = (document.getElementById('incentiveInput') || {}).value;
                var defense = (document.getElementById('defenseInput') || {}).value;
                if (!bet || !incentive || !defense) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r4'), 'warning');
                    return false;
                }
                decisions.bet = bet;
                decisions.incentive = incentive;
                decisions.defense = defense;
                return true;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var round = state.currentPeriod;
            var ds = state.domainState;
            var roundScore = 0;
            var feedback = '';

            if (round === 1) {
                // Ground truth from the concept: core IS at the top of its curve (danger),
                // the new curve is approaching crossover, and top-of-curve health is the
                // danger signal, not the all-clear.
                ds.diagnosisRight = (d.curvePos === 'top' && d.crossover === 'approaching' && d.signal === 'danger');
                var dimScore = 0;
                dimScore += (d.curvePos === 'top') ? 34 : (d.curvePos === 'mid' ? 14 : 4);
                dimScore += (d.crossover === 'approaching') ? 33 : (d.crossover === 'distant' ? 6 : 16);
                dimScore += (d.signal === 'danger') ? 33 : 6;
                roundScore = dimScore;

                if (ds.diagnosisRight) {
                    feedback = this._t('fb_r1_right');
                } else if (d.signal === 'safe') {
                    feedback = this._t('fb_r1_complacent');
                } else if (d.crossover === 'passed') {
                    feedback = this._t('fb_r1_toolate');
                } else {
                    feedback = this._t('fb_r1_partial');
                }
                // The FRI seed reflects diagnostic quality: a clear-eyed read starts the
                // readiness clock; complacency leaves the firm flat-footed.
                ds.fri = Math.round(20 + dimScore * 0.35);
            }

            if (round === 2) {
                ds.timing = d.timing;
                ds.timingLabel = this._timingLabel(d.timing);
                var year1 = d.year1;
                ds.capitalUsed = year1;
                ds.poolRemaining = this.POOL - year1;

                // Year-1 burn pressures core cash; new mix responds to commitment + timing.
                // Early + heavy commit burns cash building a market that is not ready;
                // late + light commit cedes the curve to Lumea.
                var timingMult = (d.timing === 'balanced') ? 1.0 : (d.timing === 'early' ? 0.78 : 0.62);
                var commitFactor = Math.min(1, year1 / 90); // ~CHF 90m Year-1 is a credible leap budget
                var mixGain = 0.9 + 3.6 * commitFactor * timingMult;
                ds.newMix = +(ds.newMix + mixGain).toFixed(1);

                // Burn drag on core cash in Year 1 (distraction + reinvestment).
                var burnDrag = year1 * 0.18 * (d.timing === 'early' ? 1.35 : 1.0);
                ds.coreCash = Math.round(this.BASE_CASH - burnDrag + this.BASE_CASH * 0.02);

                // Score the timing call.
                if (d.timing === 'balanced' && year1 >= 60 && year1 <= 110) {
                    roundScore = 95;
                    feedback = this._t('fb_r2_balanced');
                } else if (d.timing === 'late' || (d.timing === 'balanced' && year1 < 40)) {
                    roundScore = 40;
                    feedback = this._t('fb_r2_late');
                } else if (d.timing === 'early' && year1 > 150) {
                    roundScore = 38;
                    feedback = this._t('fb_r2_early');
                } else if (d.timing === 'early') {
                    roundScore = 62;
                    feedback = this._t('fb_r2_earlyok');
                } else {
                    roundScore = 70;
                    feedback = this._t('fb_r2_ok');
                }
                if (d.trigger === 'lumea-account') {
                    roundScore = Math.min(100, roundScore + 6);
                    feedback += '<br>' + this._t('fb_r2_trigger_good');
                } else if (d.trigger === 'proof') {
                    roundScore = Math.max(15, roundScore - 18);
                    feedback += '<br>' + this._t('fb_r2_trigger_proof');
                }
                ds.fri = this._recomputeFri(ds);
            }

            if (round === 3) {
                ds.route = d.route;
                ds.routeLabel = this._routeLabel(d.route);
                var staged = d.year23;
                ds.capitalUsed = +(ds.capitalUsed + staged).toFixed(0);
                ds.poolRemaining = this.POOL - ds.capitalUsed;

                // Capability accrual by route (control vs speed vs cost) scaled by funding.
                var totalFunding = ds.capitalUsed + d.harvest;
                var fundFactor = Math.min(1, totalFunding / 180);
                var routeBase = (d.route === 'acquire') ? 62 : (d.route === 'partner' ? 48 : 30);
                ds.capabilityBuild = Math.round(routeBase * (0.45 + 0.55 * fundFactor));

                // Reallocation tension: trimming core R&D + harvesting service cash funds
                // the build, but over-pulling collapses the cash engine (the funding bridge).
                var rdDrag = this.BASE_CASH * (d.rdCut / 100) * 0.30;       // R&D cut defends near-term cash...
                var rdGrowthLoss = (d.rdCut > 40) ? (d.rdCut - 40) * 1.4 : 0; // ...but gutting it erodes the franchise
                var harvestDrag = d.harvest * 0.55;                          // harvesting now starves future service cash
                ds.coreCash = Math.round(ds.coreCash + rdDrag * 0.6 - harvestDrag - rdGrowthLoss);

                // New mix moves with capability + staged funding.
                ds.newMix = +(ds.newMix + (ds.capabilityBuild / 100) * 4.2 + (staged / 240) * 2.0).toFixed(1);

                if (d.route === 'acquire' && d.rdCut >= 15 && d.rdCut <= 45 && d.harvest <= 60) {
                    roundScore = 92;
                    feedback = this._t('fb_r3_acquire');
                } else if (d.route === 'partner' && d.rdCut <= 35) {
                    roundScore = 80;
                    feedback = this._t('fb_r3_partner');
                } else if (d.route === 'build') {
                    roundScore = 55;
                    feedback = this._t('fb_r3_build');
                } else {
                    roundScore = 65;
                    feedback = this._t('fb_r3_ok');
                }
                if (d.rdCut > 60 || ds.coreCash < this.BASE_CASH * 0.6) {
                    roundScore = Math.max(15, roundScore - 35);
                    feedback += '<br>' + this._t('fb_r3_bridge');
                }
                if (d.rdCut < 10 && staged < 60) {
                    roundScore = Math.max(20, roundScore - 20);
                    feedback += '<br>' + this._t('fb_r3_underfund');
                }
                ds.fri = this._recomputeFri(ds);
            }

            if (round === 4) {
                ds.bet = d.bet;
                ds.betLabel = this._betLabel(d.bet);

                // Cultural relevance: culture follows structure + incentives, not slogans.
                var cultureScore = 0;
                if (d.bet === 'acquire-autonomy') cultureScore = 95;
                else if (d.bet === 'venture-unit') cultureScore = 82;
                else if (d.bet === 'inside') cultureScore = 32;
                else cultureScore = 14; // comms only

                if (d.incentive === 'yes') cultureScore = Math.min(100, cultureScore + 8);
                else if (d.incentive === 'no') cultureScore = Math.max(8, cultureScore - 22);

                // A real bet converts capability into adopted, recurring-revenue mix.
                var cultureMult = 0.55 + 0.55 * (cultureScore / 100);
                ds.capabilityBuild = Math.min(100, Math.round(ds.capabilityBuild * cultureMult + cultureScore * 0.15));
                ds.newMix = +(ds.newMix + (cultureScore / 100) * 3.4).toFixed(1);

                roundScore = cultureScore;
                if (d.bet === 'comms') feedback = this._t('fb_r4_comms');
                else if (d.bet === 'inside') feedback = this._t('fb_r4_inside');
                else if (d.bet === 'venture-unit') feedback = this._t('fb_r4_venture');
                else feedback = this._t('fb_r4_acqaut');

                if (d.incentive === 'no') feedback += '<br>' + this._t('fb_r4_inc_no');
                if (d.defense === 'harvest') {
                    roundScore = Math.max(10, roundScore - 30);
                    feedback += '<br>' + this._t('fb_r4_def_harvest');
                } else if (d.defense === 'defer') {
                    roundScore = Math.max(15, roundScore - 25);
                    feedback += '<br>' + this._t('fb_r4_def_defer');
                }
                ds.cultureScore = cultureScore;
                ds.fri = this._recomputeFri(ds);
            }

            ds.roundScore = roundScore;
            ds.friHistory.push(ds.fri);
            ds.mixHistory.push(+ds.newMix);
            ds.cashHistory.push(Math.round(ds.coreCash));
            ds.buildHistory.push(ds.capabilityBuild);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            // v1.1.0 FIX A — surface the Future Readiness Index (headline 0-100) on the
            // reporting-layer paths (express_resolveDomainScore -> performance.overallScore /
            // domainState.score; trend -> results.score/overallScore). Scoring unchanged.
            var _fri = Math.round(ds.fri);
            var _gk = _fri >= 72 ? 'grade_high' : _fri >= 55 ? 'grade_mid' : 'grade_low';
            ds.score = _fri;
            ds.performance = { overallScore: _fri, grade: this._t(_gk) };
            return {
                period: round,
                roundScore: roundScore,
                score: _fri,
                overallScore: _fri,
                fri: ds.fri,
                newMix: +ds.newMix,
                coreCash: Math.round(ds.coreCash),
                capabilityBuild: ds.capabilityBuild,
                poolRemaining: ds.poolRemaining,
                timingLabel: ds.timingLabel,
                routeLabel: ds.routeLabel,
                betLabel: ds.betLabel,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('friDisplay', 'domainState.fri', (v) => (v == null ? '—' : Math.round(v) + ' / 100'));
            uiManager.bind('mixDisplay', 'domainState.newMix', (v) => (v == null ? '—' : (+v).toFixed(1) + '%'));
            uiManager.bind('cashDisplay', 'domainState.coreCash', (v) => 'CHF ' + Math.round(v || 0) + 'm');
            uiManager.bind('buildDisplay', 'domainState.capabilityBuild', (v) => Math.round(v || 0) + ' / 100');
            uiManager.bind('poolDisplay', 'domainState.poolRemaining', (v) => 'CHF ' + Math.round(v == null ? this.POOL : v) + 'm');
        }

        getChartConfig() {
            return {
                curveChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Future Readiness Indicator',
                                data: [],
                                borderColor: '#d8232a',
                                backgroundColor: 'rgba(216, 35, 42, 0.12)',
                                borderWidth: 3,
                                tension: 0.25,
                                yAxisID: 'y',
                                fill: true
                            },
                            {
                                label: 'New-Business Mix (%)',
                                data: [],
                                borderColor: '#2e7d5b',
                                backgroundColor: 'rgba(46, 125, 91, 0.10)',
                                borderWidth: 2,
                                tension: 0.25,
