        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.score != null) ? summary.score : (summary.fri != null ? summary.fri : 0);
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="jtc-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_fri_label'), (summary.fri != null ? summary.fri : '-'))
                + metric(t('comp_mix_label'), (summary.newMix != null ? summary.newMix : '-') + '%')
                + metric(t('comp_cash_label'), '\u20ac' + (summary.coreCash != null ? summary.coreCash : '-') + 'm')
                + metric(t('comp_build_label'), (summary.capabilityBuild != null ? summary.capabilityBuild : '-'))
                + metric(t('comp_avg_label'), (summary.avgScore != null ? summary.avgScore : '-'));
            return ''
                + '<div class="jtc-completion">'
                +   '<div class="jtc-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="jtc-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="jtc-completion-metrics">' + metrics + '</div>'
                +   (summary.verdict ? '<div class="jtc-completion-verdict">' + summary.verdict + '</div>' : '')
                +   (items ? '<ul class="jtc-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = (history[history.length - 1] || {}).results || {};
            var fri = last.fri || 0;
            var mix = last.newMix || 0;
            var cash = last.coreCash || 0;
            var build = last.capabilityBuild || 0;
            var scores = history.map(r => (r.results && r.results.roundScore) || 0);
            var avg = Math.round(scores.reduce((s, p) => s + p, 0) / scores.length);

            var verdict = this._t('verdict_low');
            if (fri >= 72 && cash >= this.BASE_CASH * 0.7 && mix >= 12) verdict = this._t('verdict_high');
            else if (fri >= 55 && cash >= this.BASE_CASH * 0.6) verdict = this._t('verdict_mid');

            var insights = [];
            if (cash < this.BASE_CASH * 0.6) insights.push(this._t('insight_bridge_broken'));
            if (mix < 8) insights.push(this._t('insight_mix_stalled'));
            if (build < 45) insights.push(this._t('insight_capability_thin'));
            if (fri >= 72 && cash >= this.BASE_CASH * 0.7 && mix >= 12) insights.push(this._t('insight_clean_leap'));
            if (!insights.length) insights.push(this._t('insight_default'));

            return {
                avgScore: avg,
                score: Math.round(fri),
                fri: Math.round(fri),
                newMix: +mix.toFixed(1),
                coreCash: Math.round(cash),
                capabilityBuild: Math.round(build),
                verdict: verdict,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results && results.feedback) return results.feedback;
            return null;
        }

