        // ---- helpers ----

        _t(key) {
            try {
                return (window.mySimulation && window.mySimulation.t)
                    ? window.mySimulation.t(key)
                    : key;
            } catch (e) { return key; }
        }

        _recomputeFri(ds) {
            // Composite of the concept's dimensions:
            //   advantage durability (core cash held vs base), migration ability (mix + capability),
            //   resources/timing (diagnosis + capital discipline), culture (set in R4).
            var durability = Math.max(0, Math.min(40, (ds.coreCash / this.BASE_CASH) * 40));
            var migration = Math.min(40, (Math.min(ds.newMix, 20) / 20) * 24 + (ds.capabilityBuild / 100) * 16);
            var resources = ds.diagnosisRight ? 12 : 5;
            var culture = (typeof ds.cultureScore === 'number') ? (ds.cultureScore / 100) * 8 : 0;
            var fri = durability + migration + resources + culture;
            return Math.max(0, Math.min(100, Math.round(fri)));
        }

        _timingLabel(key) {
            var map = { 'late': this._t('timing_late'), 'balanced': this._t('timing_balanced'), 'early': this._t('timing_early') };
            return map[key] || '—';
        }
        _routeLabel(key) {
            var map = { 'build': this._t('route_build'), 'partner': this._t('route_partner'), 'acquire': this._t('route_acquire') };
            return map[key] || '—';
        }
        _betLabel(key) {
            var map = {
                'comms': this._t('bet_comms'),
                'inside': this._t('bet_inside'),
                'venture-unit': this._t('bet_venture'),
                'acquire-autonomy': this._t('bet_acqaut')
            };
            return map[key] || '—';
        }

        _updateBriefing(state) {
            var round = (state && state.currentPeriod) || 1;
            if (round > 4) round = 4;
            if (round < 1) round = 1;

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var nameEl = document.getElementById('roundName');

            var titleKey = 'round' + round + '_title';
            var textKey = 'round' + round + '_text';

            if (titleEl) titleEl.textContent = this._t(titleKey);
            if (textEl) textEl.innerHTML = this._t(textKey);
            if (nameEl) nameEl.textContent = this._t(titleKey);

            for (var i = 1; i <= 4; i++) {
                var panel = document.getElementById('round' + i + 'Controls');
                if (panel) panel.style.display = (i === round) ? 'block' : 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new JumpCurveAdapter(), {
            simulationType: 'jump_the_curve',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

